/**
 * Read-old gate: files written by the published modern-pdf-lib@0.40.3 must still be read, and
 * re-saved, by the current source ("read old, write new").
 *
 * The fixtures in tests/fixtures/legacy-0.40.3 are generated by
 * scripts/legacy-0.40.3/generate.ts from the npm tarball, never from this tree. The per-fixture
 * expected values (page count, Info strings, page text, field values, encryption parameters,
 * signature field name) come from manifest.json, which the generator writes from the same source
 * values it used to build the files. The signer name, the SubFilter, the raw-byte `/V /Yes`
 * pattern the independent-reader check uses for the `agree` box and the reader's error messages
 * are literals in this file.
 *
 * Every re-save ("write new") goes to outside readers as well: each re-save test passes its
 * output to `qpdf --check` (expectQpdfClean, after its own assertions), and one test per fixture
 * re-saves with `compress: false` and asks qpdf and then pdf.js for the page text. A test that
 * runs qpdf skips with a reason where qpdf is absent locally and fails when `CI` is set.
 *
 * The encrypted fixtures open with their user and with their owner password. A document
 * decrypted on load is never saved in clear: a bare save() throws UnsupportedEncryptionError, so
 * each re-save of an encrypted fixture first calls encrypt() with new passwords and its own
 * algorithm; the output then opens in qpdf and pdf.js with the new user password, and its
 * plaintext (`qpdf --decrypt`, loaded by the library) holds the source's page text and Title.
 * encrypted-r6.pdf is AES-256 with the key derivation 0.40.3 wrote: opening it emits exactly one
 * MPL_LEGACY_R6_KEY warning per realm, and no other fixture emits one.
 *
 * A check that fails today because of a known open defect is a knownDefect marker
 * (tests/helpers/known-defect.ts): a `test.fails` whose title starts with the defect id and the
 * release that fixes it, and which passes only while the check fails with the error KNOWN names.
 * When that defect is fixed the marker turns red; the fixing release flips the entry in KNOWN to
 * a plain `test` by deleting it.
 */
import { Buffer } from 'node:buffer';
import { createHash } from 'node:crypto';
import { readdirSync, readFileSync } from 'node:fs';
import { inflateRawSync, inflateSync } from 'node:zlib';
import { PDFDocument } from 'pdf-lib';
import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest';
import type { MockInstance, TestContext } from 'vitest';
import {
  extractText,
  isLinearized,
  loadPdf,
  parseContentStream,
  UnsupportedEncryptionError,
  verifySignatures,
} from '../../src/index.js';
import type { PdfDocument } from '../../src/index.js';
import { resetWarningsForTesting } from '../../src/utils/warnings.js';
import { defectKey, knownDefect } from '../helpers/known-defect.js';
import type { DefectKey } from '../helpers/known-defect.js';
import { pdfjsText } from '../helpers/oracle/pdfjs.js';
import { expectQpdfClean, qpdfDecryptQdf, requireQpdf } from '../helpers/oracle/qpdf.js';

type Check =
  | 'info'
  | 'text'
  | 'resaveCount'
  | 'resaveOracles'
  | 'resaveInfo'
  | 'resaveText'
  | 'resaveUniqueObjects'
  | 'fields'
  | 'signatureFieldName';

interface LegacyExpect {
  readonly pageCount: number;
  readonly info?: { readonly Title: string; readonly Author: string; readonly Subject?: string };
  readonly pageText: readonly string[];
  readonly fields?: Readonly<Record<string, string | boolean>>;
  readonly encryption?: {
    readonly V: number;
    readonly R: number;
    readonly CFM: string;
    readonly userPassword: string;
    readonly ownerPassword: string;
  };
  readonly linearized?: true;
  readonly signature?: { readonly fieldName: string; readonly subFilter: string };
}

interface LegacyEntry {
  readonly file: string;
  readonly sha256: string;
  readonly bytes: number;
  readonly producer: string;
  readonly api: string;
  readonly inputs: Readonly<Record<string, unknown>>;
  readonly expect: LegacyExpect;
  readonly notes?: string;
}

const DIR = new URL('../fixtures/legacy-0.40.3/', import.meta.url);
const manifest = JSON.parse(readFileSync(new URL('manifest.json', DIR), 'utf8')) as LegacyEntry[];

const bytesOf = (file: string): Uint8Array => new Uint8Array(readFileSync(new URL(file, DIR)));
const sha256 = (bytes: Uint8Array): string => createHash('sha256').update(bytes).digest('hex');
const latin1 = (bytes: Uint8Array): string => Buffer.from(bytes).toString('latin1');
const entryOf = (file: string): LegacyEntry => {
  const entry = manifest.find((m) => m.file === file);
  if (entry === undefined) throw new Error(`manifest has no entry for ${file}`);
  return entry;
};

// Known open defects, one place, so each id appears once. fixture -> check -> key and the
// error the check shows while the defect is open (knownDefect passes only on that error).
// A listed check runs as a knownDefect marker; delete the entry in the release that fixes the defect.
interface Known {
  readonly key: DefectKey;
  readonly failsWith: RegExp;
}
// Each pattern names the labelled assertion it comes from (the second argument of expect()).
const TITLE_DIFFERS = /^AssertionError: Info Title: expected .* to be '/;
const TEXT_DIFFERS =
  /^AssertionError: page \d+ text \((?:library|pdf\.js)\): expected .* to contain '/;
const DUPLICATE_OBJECTS: Known = {
  key: defectKey('legacy-M01', '0.41.2'),
  failsWith: /^AssertionError: distinct object numbers: expected \d+ to be \d+/,
};
const UTF8_INFO: Known = { key: defectKey('core-document-01', '0.41.0'), failsWith: TITLE_DIFFERS };
const UTF8_TEXT: Known = { key: defectKey('core-page-01', '0.41.0'), failsWith: TEXT_DIFFERS };
const KNOWN: Readonly<Record<string, Partial<Record<Check, Known>>>> = {
  'raw-deflate.pdf': { resaveUniqueObjects: DUPLICATE_OBJECTS },
  'raw-deflate-objstm.pdf': { resaveUniqueObjects: DUPLICATE_OBJECTS },
  'linearized.pdf': { resaveUniqueObjects: DUPLICATE_OBJECTS },
  'signed.pdf': {
    signatureFieldName: {
      key: defectKey('signature-cms-38', '0.45.0'),
      failsWith: /^AssertionError: expected 'Signature' to be 'Signature1'/,
    },
    resaveUniqueObjects: DUPLICATE_OBJECTS,
  },
  'forms.pdf': {
    fields: {
      key: defectKey('forms-34', '0.41.5'),
      failsWith: /^AssertionError: hasForm\(\): expected false to be true/,
    },
    resaveUniqueObjects: DUPLICATE_OBJECTS,
  },
  'utf8-strings.pdf': {
    info: UTF8_INFO,
    text: UTF8_TEXT,
    resaveInfo: UTF8_INFO,
    resaveText: UTF8_TEXT,
    // compress: false passes qpdf; pdf.js then shows the UTF-8 bytes as WinAnsi characters.
    resaveOracles: UTF8_TEXT,
    resaveUniqueObjects: DUPLICATE_OBJECTS,
  },
};

/** `test` for a passing check, a knownDefect marker (key in the title) for a known defect. */
function check(
  file: string,
  c: Check,
  what: string,
  body: (ctx: TestContext) => Promise<void> | void,
): void {
  const known = KNOWN[file]?.[c];
  if (known === undefined) test(`${file} ${what}`, body);
  else knownDefect(known.key, `${file} ${what}`, { failsWith: known.failsWith }, body);
}

const loadOptions = (entry: LegacyEntry): { password: string } | undefined =>
  entry.expect.encryption === undefined
    ? undefined
    : { password: entry.expect.encryption.userPassword };

async function load(entry: LegacyEntry): Promise<PdfDocument> {
  const options = loadOptions(entry);
  const bytes = bytesOf(entry.file);
  return options === undefined ? loadPdf(bytes) : loadPdf(bytes, options);
}

/** The new passwords a re-save of an encrypted fixture is encrypted with. */
const RESAVE_USER = 'user-resave';
const RESAVE_OWNER = 'owner-resave';

/**
 * A re-save of `entry`. An encrypted fixture is given encrypt() with the RESAVE passwords and
 * the algorithm it was written with first: a bare save() of a decrypted document throws.
 */
async function resave(entry: LegacyEntry, options?: { compress: false }): Promise<Uint8Array> {
  const doc = await load(entry);
  if (entry.expect.encryption !== undefined) {
    await doc.encrypt({
      userPassword: RESAVE_USER,
      ownerPassword: RESAVE_OWNER,
      algorithm: entry.inputs['algorithm'] as 'aes-128' | 'aes-256',
    });
  }
  return options === undefined ? doc.save() : doc.save(options);
}

/** The options that open a re-save of `entry`: the RESAVE user password when it is encrypted. */
const resaveOptions = (entry: LegacyEntry): { password?: string } =>
  entry.expect.encryption === undefined ? {} : { password: RESAVE_USER };

function pageText(doc: PdfDocument, index: number): string {
  return extractText(parseContentStream(doc.getPage(index).getContentStream()));
}

/** The raw, still-compressed bytes of every /FlateDecode stream (the file is written with direct /Length). */
function flateStreams(bytes: Uint8Array): Uint8Array[] {
  const text = latin1(bytes);
  const found: Uint8Array[] = [];
  for (const m of text.matchAll(/(?<!end)stream\r?\n/g)) {
    const start = m.index + m[0].length;
    const header = text.slice(text.lastIndexOf(' obj', m.index), m.index);
    if (!header.includes('/FlateDecode')) continue;
    const length = /\/Length (\d+)/.exec(header)?.[1];
    if (length === undefined) throw new Error('FlateDecode stream without a direct /Length');
    found.push(bytes.subarray(start, start + Number(length)));
  }
  return found;
}

/** Object numbers of every `N G obj` header, in file order. */
function objectNumbers(bytes: Uint8Array): number[] {
  return [...latin1(bytes).matchAll(/(?:^|[\r\n])(\d+) \d+ obj\b/g)].map((m) => Number(m[1]));
}

describe('legacy-0.40.3 fixture set', () => {
  test('manifest matches the directory and every file hash', () => {
    const onDisk = readdirSync(DIR)
      .filter((n) => n.endsWith('.pdf'))
      .sort();
    expect(manifest.map((m) => m.file).sort()).toEqual(onDisk);
    expect(onDisk).toHaveLength(8);
    for (const entry of manifest) {
      expect(entry.producer).toBe('modern-pdf-lib@0.40.3');
      const bytes = bytesOf(entry.file);
      expect(bytes.length, `${entry.file} size`).toBe(entry.bytes);
      expect(sha256(bytes), `${entry.file} sha256`).toBe(entry.sha256);
    }
  });

  test.each(['raw-deflate.pdf', 'raw-deflate-objstm.pdf'])(
    '%s holds raw DEFLATE streams, not zlib',
    (file) => {
      const streams = flateStreams(bytesOf(file));
      expect(streams.length).toBeGreaterThan(0);
      for (const s of streams) {
        expect(() => inflateRawSync(s)).not.toThrow();
        expect(() => inflateSync(s)).toThrow();
      }
    },
  );

  test('raw-deflate-objstm.pdf holds an object stream and an xref stream', () => {
    const text = latin1(bytesOf('raw-deflate-objstm.pdf'));
    expect(text).toContain('/Type /ObjStm');
    expect(text).toContain('/Type /XRef');
  });

  test('utf8-strings.pdf holds UTF-8 in a literal string', () => {
    const title = entryOf('utf8-strings.pdf').expect.info?.Title;
    expect(title).toBeDefined();
    const literal = Buffer.from(`/Title (${title})`, 'utf8').toString('latin1');
    expect(latin1(bytesOf('utf8-strings.pdf'))).toContain(literal);
  });

  test('forms.pdf holds the field values (independent reader)', async () => {
    const entry = entryOf('forms.pdf');
    const pdf = await PDFDocument.load(bytesOf('forms.pdf'), { updateMetadata: false });
    const form = pdf.getForm();
    expect(form.getTextField('name').getText()).toBe(entry.expect.fields?.['name']);
    expect(form.getDropdown('colour').getSelected()).toEqual([entry.expect.fields?.['colour']]);
    expect(latin1(bytesOf('forms.pdf'))).toMatch(/\/T \(agree\)[^>]*\/V \/Yes/);
  });

  for (const entry of manifest) {
    const { file, expect: want } = entry;
    describe(file, () => {
      test(`${file} loads with the current reader`, async () => {
        await expect(load(entry)).resolves.toBeDefined();
      });

      test(`${file} page count`, async () => {
        expect((await load(entry)).getPageCount()).toBe(want.pageCount);
      });

      check(file, 'info', 'info strings', async () => {
        const doc = await load(entry);
        if (want.info === undefined) {
          expect(doc.getTitle()).toBeUndefined();
          return;
        }
        expect(doc.getTitle(), 'Info Title').toBe(want.info.Title);
        expect(doc.getAuthor()).toBe(want.info.Author);
        if (want.info.Subject !== undefined) expect(doc.getSubject()).toBe(want.info.Subject);
      });

      check(file, 'text', 'page text', async () => {
        const doc = await load(entry);
        want.pageText.forEach((t, i) => {
          expect(pageText(doc, i), `page ${i + 1} text (library)`).toContain(t);
        });
      });

      check(file, 'resaveCount', 're-save loads again with the same page count', async (ctx) => {
        requireQpdf(ctx);
        const out = await resave(entry);
        expect((await loadPdf(out, resaveOptions(entry))).getPageCount()).toBe(want.pageCount);
        expectQpdfClean(out, resaveOptions(entry));
      });

      check(file, 'resaveText', 're-save keeps page text', async (ctx) => {
        requireQpdf(ctx);
        const out = await resave(entry);
        const reloaded = await loadPdf(out, resaveOptions(entry));
        want.pageText.forEach((t, i) => {
          expect(pageText(reloaded, i), `page ${i + 1} text (library)`).toContain(t);
        });
        expectQpdfClean(out, resaveOptions(entry));
      });

      check(file, 'resaveInfo', 're-save keeps the Title', async (ctx) => {
        requireQpdf(ctx);
        const out = await resave(entry);
        expect((await loadPdf(out, resaveOptions(entry))).getTitle(), 'Info Title').toBe(
          want.info?.Title,
        );
        expectQpdfClean(out, resaveOptions(entry));
      });

      check(
        file,
        'resaveOracles',
        're-save (compress: false) passes qpdf --check and pdf.js shows the page text',
        async (ctx) => {
          requireQpdf(ctx);
          const out = await resave(entry, { compress: false });
          expectQpdfClean(out, resaveOptions(entry));
          const text = await pdfjsText(out, resaveOptions(entry));
          expect(text).toHaveLength(want.pageCount);
          want.pageText.forEach((t, i) => {
            expect(text[i], `page ${i + 1} text (pdf.js)`).toContain(t);
          });
        },
      );

      const encryption = want.encryption;
      if (encryption !== undefined) {
        test(`${file} opens with its owner password`, async () => {
          const doc = await loadPdf(bytesOf(file), { password: encryption.ownerPassword });
          expect(doc.getTitle(), 'Info Title').toBe(want.info?.Title);
          want.pageText.forEach((t, i) => {
            expect(pageText(doc, i), `page ${i + 1} text (library)`).toContain(t);
          });
        });

        test(`${file} a bare save() of the decrypted document throws UnsupportedEncryptionError`, async () => {
          await expect((await load(entry)).save()).rejects.toThrow(UnsupportedEncryptionError);
        });

        test(`${file} re-save: its plaintext (qpdf --decrypt) holds the page text and the Title`, async (ctx) => {
          requireQpdf(ctx);
          const out = await resave(entry);
          expectQpdfClean(out, resaveOptions(entry));
          const plain = await loadPdf(qpdfDecryptQdf(out, RESAVE_USER));
          expect(plain.getTitle(), 'Info Title').toBe(want.info?.Title);
          want.pageText.forEach((t, i) => {
            expect(pageText(plain, i), `page ${i + 1} text (qpdf plaintext)`).toContain(t);
          });
        });
      } else {
        check(
          file,
          'resaveUniqueObjects',
          're-save defines each object number once',
          async (ctx) => {
            requireQpdf(ctx);
            const out = await (await load(entry)).save({ compress: false });
            const numbers = objectNumbers(out);
            expect(numbers.length).toBeGreaterThan(0);
            expect(new Set(numbers).size, 'distinct object numbers').toBe(numbers.length);
            expectQpdfClean(out);
          },
        );
      }
    });
  }

  test('linearized.pdf is linearized', () => {
    expect(entryOf('linearized.pdf').expect.linearized).toBe(true);
    expect(isLinearized(bytesOf('linearized.pdf'))).toBe(true);
  });

  test.each(['encrypted-r4.pdf', 'encrypted-r6.pdf'])(
    '%s rejects a wrong password and a missing one',
    async (file) => {
      const bytes = bytesOf(file);
      await expect(loadPdf(bytes, { password: 'wrong' })).rejects.toThrow(/password is incorrect/);
      await expect(loadPdf(bytes)).rejects.toThrow(/requires a password/);
    },
  );

  test('encrypted fixtures carry the encryption the manifest names', () => {
    for (const file of ['encrypted-r4.pdf', 'encrypted-r6.pdf']) {
      const enc = entryOf(file).expect.encryption;
      expect(enc).toBeDefined();
      const text = latin1(bytesOf(file));
      expect(text).toContain(`/V ${enc?.V}`);
      expect(text).toContain(`/R ${enc?.R}`);
      expect(text).toContain(`/CFM /${enc?.CFM}`);
    }
  });

  // Integrity only: trust fields (valid, certificateValid, chain) change in 0.40.5 and are not
  // part of what a legacy file promises.
  test('signed.pdf signature integrity', async () => {
    const want = entryOf('signed.pdf').expect.signature;
    expect(want?.subFilter).toBe('adbe.pkcs7.detached');
    const [signature, ...rest] = await verifySignatures(bytesOf('signed.pdf'));
    expect(rest).toHaveLength(0);
    expect(signature?.integrityValid).toBe(true);
    expect(signature?.signedBy).toBe('Legacy 0.40.3 Test Signer');
  });

  check('signed.pdf', 'signatureFieldName', 'signature field name', async () => {
    const [signature] = await verifySignatures(bytesOf('signed.pdf'));
    expect(signature?.fieldName).toBe(entryOf('signed.pdf').expect.signature?.fieldName);
  });

  describe('MPL_LEGACY_R6_KEY', () => {
    let emitWarning: MockInstance<typeof process.emitWarning>;
    beforeEach(() => {
      resetWarningsForTesting();
      emitWarning = vi.spyOn(process, 'emitWarning').mockImplementation(() => {});
    });
    afterEach(() => {
      vi.restoreAllMocks();
      resetWarningsForTesting();
    });
    const legacyCalls = (): unknown[][] =>
      emitWarning.mock.calls.filter(
        (call: unknown[]) =>
          (call[1] as { code?: string } | undefined)?.code === 'MPL_LEGACY_R6_KEY',
      );

    test('encrypted-r6.pdf opens with its user and its owner password and warns once per realm', async () => {
      const enc = entryOf('encrypted-r6.pdf').expect.encryption;
      const bytes = bytesOf('encrypted-r6.pdf');
      await loadPdf(bytes, { password: enc?.userPassword ?? '' });
      expect(legacyCalls()).toHaveLength(1);
      await loadPdf(bytes, { password: enc?.ownerPassword ?? '' });
      expect(legacyCalls()).toHaveLength(1);
      expect(legacyCalls()[0]?.[1]).toEqual({
        type: 'ModernPdfLibWarning',
        code: 'MPL_LEGACY_R6_KEY',
      });
    });

    test('encrypted-r6.pdf opened with its owner password alone warns once', async () => {
      const enc = entryOf('encrypted-r6.pdf').expect.encryption;
      await loadPdf(bytesOf('encrypted-r6.pdf'), { password: enc?.ownerPassword ?? '' });
      expect(legacyCalls()).toHaveLength(1);
    });

    test('no other fixture warns', async () => {
      const others = manifest.filter((m) => m.file !== 'encrypted-r6.pdf');
      expect(others).toHaveLength(7);
      for (const entry of others) {
        await load(entry);
        const enc = entry.expect.encryption;
        if (enc !== undefined) await loadPdf(bytesOf(entry.file), { password: enc.ownerPassword });
      }
      expect(legacyCalls()).toEqual([]);
    });
  });

  check('forms.pdf', 'fields', 'field values through the current reader', async () => {
    const want = entryOf('forms.pdf').expect.fields;
    const doc = await load(entryOf('forms.pdf'));
    expect(doc.hasForm(), 'hasForm()').toBe(true);
    const form = doc.getForm();
    expect(form.getTextField('name').getText()).toBe(want?.['name']);
    expect(form.getCheckbox('agree').isChecked()).toBe(want?.['agree']);
    expect(form.getDropdown('colour').getSelected()).toBe(want?.['colour']);
  });
});
